import type { BankQuestion } from "@/lib/bank";

/** Work, Energy, Power and Collisions (Physics (JEE/NEET)): 128 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"phy-work-energy-power-1","question":"The kinetic energy of a 2 kg body moving at 3 m/s is:","options":["9 J","18 J","6 J","3 J"],"answer":0,"explanation":"KE = ½mv² = ½ × 2 × 9 = 9 J. Forgetting the ½ gives 18 J.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-work-energy-power-2","question":"The work done by the centripetal force on a body in uniform circular motion during one revolution is:","options":["positive","zero","negative","equal to its kinetic energy"],"answer":1,"explanation":"The centripetal force is always perpendicular to the displacement, so F·ds = 0 at every instant and the total work is zero; the speed stays constant.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-work-energy-power-3","question":"The SI unit of power is:","options":["joule","watt","newton","erg"],"answer":1,"explanation":"Power is the rate of doing work, measured in watt = joule per second. Horsepower (1 hp ≈ 746 W) is a non-SI unit.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-work-energy-power-4","question":"A force F = (2i + 3j) N acts on a particle that undergoes a displacement s = (4i − 2j) m. The work done by the force is:","options":["2 J","8 J","14 J","−2 J"],"answer":0,"explanation":"W = F·s = 2 × 4 + 3 × (−2) = 8 − 6 = 2 J. Adding the products instead of taking signs gives 14 J.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-work-energy-power-5","question":"If the momentum of a body is doubled, its kinetic energy becomes:","options":["4 times","2 times","√2 times","unchanged"],"answer":0,"explanation":"KE = p²/2m, so doubling p (at fixed mass) makes the kinetic energy 4 times. Conversely, doubling KE increases p only by √2.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-work-energy-power-6","question":"A spring of force constant 200 N/m is stretched by 10 cm. The potential energy stored in it is:","options":["2 J","0.1 J","10 J","1 J"],"answer":3,"explanation":"U = ½kx² = ½ × 200 × (0.1)² = 1 J. Using x = 10 instead of 0.1 m gives a wildly wrong value.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-work-energy-power-7","question":"A pump lifts 100 kg of water every second to a height of 10 m (g = 10 m/s²). Neglecting the kinetic energy given to the water, the power of the pump is:","options":["1 kW","100 W","100 kW","10 kW"],"answer":3,"explanation":"P = (dm/dt) g h = 100 × 10 × 10 = 10⁴ W = 10 kW.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-work-energy-power-8","question":"Ball A moving at 5 m/s collides head-on elastically with an identical ball B at rest. After the collision:","options":["both move together at 2.5 m/s","A stops and B moves at 5 m/s","A rebounds at 5 m/s and B stays at rest","both move forward at 5 m/s"],"answer":1,"explanation":"For equal masses in a one-dimensional elastic collision the velocities are exchanged: A comes to rest and B moves off at 5 m/s. Moving together at 2.5 m/s would be a perfectly inelastic collision.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-work-energy-power-9","question":"A 2 kg particle is at x = 0 and a 3 kg particle is at x = 5 m. The centre of mass of the system is at:","options":["2 m","2.5 m","3 m","3.5 m"],"answer":2,"explanation":"x_cm = (2 × 0 + 3 × 5)/(2 + 3) = 15/5 = 3 m, closer to the heavier particle. The midpoint 2.5 m would be right only for equal masses.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-work-energy-power-10","question":"A 2 kg block on a rough horizontal surface (μ = 0.3, g = 10 m/s²) is pulled from rest by a horizontal force of 10 N through 5 m. Its kinetic energy at the end is:","options":["50 J","20 J","30 J","80 J"],"answer":1,"explanation":"Work–energy theorem: W_F + W_f = ΔKE, so 10 × 5 − 0.3 × 20 × 5 = 50 − 30 = 20 J. The 50 J option ignores the work done against friction.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-work-energy-power-11","question":"The potential energy of a particle moving along the x-axis is U(x) = 2x² − 4x joule (x in metres). The particle is in stable equilibrium at:","options":["x = 0","x = 1 m","x = 2 m","x = −1 m"],"answer":1,"explanation":"F = −dU/dx = −(4x − 4) = 0 at x = 1 m, and d²U/dx² = 4 > 0 (a minimum of U), so the equilibrium is stable.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-work-energy-power-12","question":"A 1000 kg car moves at a constant 20 m/s on a level road against a total resistive force of 500 N. The power delivered by its engine is:","options":["5 kW","20 kW","100 kW","10 kW"],"answer":3,"explanation":"At constant velocity the engine force equals the resistance, so P = Fv = 500 × 20 = 10⁴ W = 10 kW. The mass is irrelevant here since there is no acceleration.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-work-energy-power-13","question":"A 2 kg body moving at 6 m/s collides with a 4 kg body at rest and the two stick together. The kinetic energy lost in the collision is:","options":["24 J","36 J","12 J","18 J"],"answer":0,"explanation":"Momentum: 2 × 6 = 6v, v = 2 m/s. KE before = ½ × 2 × 36 = 36 J; after = ½ × 6 × 4 = 12 J; loss = 24 J (two-thirds of the initial KE, i.e. the fraction M/(m + M)).","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-work-energy-power-14","question":"A ball dropped from a height of 5 m onto a floor rebounds to a height of 1.25 m. The coefficient of restitution between the ball and the floor is:","options":["0.5","0.25","1/√2","0.75"],"answer":0,"explanation":"e = v_rebound/v_impact = √(2gh₂)/√(2gh₁) = √(h₂/h₁) = √(1.25/5) = √0.25 = 0.5. Taking the ratio of heights directly gives 0.25, the square of e.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-work-energy-power-15","question":"A 0.5 kg bob hangs from a 1 m string. It is pulled aside until the string is horizontal and released (g = 10 m/s²). The tension in the string at the lowest point is:","options":["5 N","10 N","20 N","15 N"],"answer":3,"explanation":"Energy conservation: v² = 2gL = 20 m²/s². At the bottom T = mg + mv²/L = 0.5 × 10 + 0.5 × 20 = 15 N, i.e. 3mg.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-work-energy-power-16","question":"A force F = 3x² N acts on a particle along the x-axis. The work done by the force in moving the particle from x = 0 to x = 2 m is:","options":["4 J","12 J","6 J","8 J"],"answer":3,"explanation":"W = ∫₀² 3x² dx = [x³]₀² = 8 J. Multiplying the force at x = 2 (12 N) by the displacement gives 24 J, which is wrong because the force varies.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-work-energy-power-17","question":"Particles of 1 kg, 1 kg and 2 kg are placed at (0, 0), (2, 0) and (0, 2) metres respectively. The centre of mass is at:","options":["(1, 0.5)","(0.5, 1)","(1, 1)","(2/3, 2/3)"],"answer":1,"explanation":"x_cm = (0 + 2 + 0)/4 = 0.5 m and y_cm = (0 + 0 + 4)/4 = 1 m. (2/3, 2/3) would be the centroid for three equal masses.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-work-energy-power-18","question":"A body starts from rest and moves with constant acceleration under a constant force. The instantaneous power delivered by the force is:","options":["constant","proportional to t²","proportional to √t","proportional to t"],"answer":3,"explanation":"P = Fv with F constant and v = at, so P ∝ t. (The total work done, ½mv², grows as t².)","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-work-energy-power-19","question":"A block slides from rest down a smooth incline of height 5 m and then onto a rough horizontal surface with μ = 0.25 (g = 10 m/s²). The distance it travels on the rough surface before stopping is:","options":["20 m","25 m","10 m","40 m"],"answer":0,"explanation":"At the bottom v² = 2gh = 100 m²/s². On the rough surface friction does work μmgs = ½mv², so s = v²/(2μg) = 100/(2 × 0.25 × 10) = 20 m. The mass cancels.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-work-energy-power-20","question":"How many of the following statements about collisions are correct?\n(A) In an elastic collision the kinetic energy is conserved at every instant during the collision.\n(B) Linear momentum is conserved in every collision in the absence of external impulsive forces.\n(C) In a perfectly inelastic collision the loss of kinetic energy is the maximum consistent with momentum conservation.\n(D) The coefficient of restitution lies between 0 and 1.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(B), (C) and (D) are correct. (A) is false — during an elastic collision part of the KE is temporarily stored as elastic potential energy at maximum compression; only the KE before and after the collision are equal.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-work-energy-power-21","question":"A particle moving at 10 m/s makes an oblique elastic collision with an identical particle at rest. After the collision the first particle moves at 6 m/s. The speed of the second particle is:","options":["4 m/s","6 m/s","10 m/s","8 m/s"],"answer":3,"explanation":"For equal masses in an oblique elastic collision with one at rest, the final velocities are perpendicular and KE is conserved: 10² = 6² + v², so v = 8 m/s. The result 4 m/s wrongly assumes the speeds add like scalars.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-work-energy-power-22","question":"A 2 kg block sliding at 4 m/s on a smooth floor hits a light spring of force constant 800 N/m. The maximum compression of the spring is:","options":["0.1 m","0.2 m","0.4 m","0.05 m"],"answer":1,"explanation":"At maximum compression the block is momentarily at rest: ½mv² = ½kx², so x = v√(m/k) = 4 × √(2/800) = 4 × (1/20) = 0.2 m.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-work-energy-power-23","question":"A 10 g bullet moving at 400 m/s embeds itself in a 1.99 kg block hanging from a long string (g = 10 m/s²). The height to which the block rises is:","options":["0.4 m","0.1 m","0.8 m","0.2 m"],"answer":3,"explanation":"Momentum conservation in the collision: 0.01 × 400 = 2 × v, v = 2 m/s. Then energy conservation in the swing: h = v²/2g = 4/20 = 0.2 m. Applying energy conservation to the collision itself would be wrong, since it is inelastic.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-work-energy-power-24","question":"A pump throws water out of a pipe of fixed cross-section at speed v. If the speed of ejection is doubled, the power required becomes:","options":["2 times","4 times","16 times","8 times"],"answer":3,"explanation":"Mass flow rate dm/dt = ρAv and the KE given per second is ½(dm/dt)v² = ½ρAv³, so P ∝ v³ and doubling v makes the power 8 times.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-work-energy-power-25","question":"The potential energy of a particle is U(x) = x³ − 3x joule (x in metres). The position of unstable equilibrium is:","options":["x = 1 m","x = 0","x = −1 m","x = √3 m"],"answer":2,"explanation":"dU/dx = 3x² − 3 = 0 at x = ±1. d²U/dx² = 6x is negative at x = −1 (a maximum of U, unstable) and positive at x = 1 (stable). x = ±√3 are just the zeros of U, not equilibria.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-work-energy-power-26","question":"Assertion (A): The work done by friction on a body can be positive.\nReason (R): When a block rests on a plank that is accelerated by an external force, static friction on the block acts along its displacement.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Friction on the upper block points forward (it is what accelerates the block) and the block moves forward, so friction does positive work on it; R correctly explains A.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-work-energy-power-27","question":"A 60 kg man stands at one end of a 120 kg boat floating at rest on still water. He walks 3 m towards the other end relative to the boat. Neglecting water resistance, the boat moves:","options":["2 m","1 m","0.5 m","1.5 m"],"answer":1,"explanation":"With no external horizontal force the centre of mass stays fixed: 60(3 − x) = 120x, so x = 1 m backward. The man moves 2 m relative to the water.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-work-energy-power-28","question":"A body at rest explodes into three fragments. Two fragments, each of mass m, fly off perpendicular to each other with speed v. The third fragment has mass 2m. Its speed is:","options":["v√2","v/2","v/√2","2v"],"answer":2,"explanation":"The two momenta mv at right angles combine to mv√2, so the third fragment must carry momentum mv√2 in the opposite direction: 2m × v₃ = mv√2, v₃ = v/√2.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-work-energy-power-29","question":"A uniform chain of mass m and length L lies on a smooth table with one-third of its length hanging over the edge. The work needed to pull the hanging part back onto the table is:","options":["mgL/6","mgL/9","mgL/18","mgL/3"],"answer":2,"explanation":"The hanging part has mass m/3 and its centre of mass is L/6 below the table top, so W = (m/3) g (L/6) = mgL/18.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-work-energy-power-30","question":"A body starts from rest and is driven by a source of constant power. Its displacement in time t is proportional to:","options":["t²","t^(3/2)","t","√t"],"answer":1,"explanation":"Pt = ½mv² gives v ∝ t^(1/2); integrating, s ∝ t^(3/2). The velocity is not constant, so s ∝ t is wrong.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-work-energy-power-31","question":"A 2 kg body falls freely through 5 m (g = 10 m/s²). The work done on it by gravity is:","options":["200 J","10 J","100 J","50 J"],"answer":2,"explanation":"W = mgh = 2 × 10 × 5 = 100 J; it is positive because the force and the displacement are both downward.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"phy-work-energy-power-32","question":"A body of mass 5 kg has a momentum of 10 kg m/s. Its kinetic energy is:","options":["50 J","5 J","20 J","10 J"],"answer":3,"explanation":"K = p²/2m = 100/10 = 10 J. Using pv (= 20 J) without the half doubles it.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-work-energy-power-33","question":"A lift of total mass 500 kg moves up at a constant speed of 2 m/s (g = 10 m/s², no friction). The power delivered by the motor is:","options":["10 kW","5 kW","20 kW","1 kW"],"answer":0,"explanation":"At constant speed the motor force equals the weight, 5000 N, and P = Fv = 5000 × 2 = 10⁴ W = 10 kW.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-work-energy-power-34","question":"A spring of force constant 100 N/m is stretched from an extension of 10 cm to an extension of 20 cm. The work done in this step is:","options":["1 J","1.5 J","2 J","0.5 J"],"answer":1,"explanation":"W = ½k(x₂² − x₁²) = ½ × 100 × (0.04 − 0.01) = 1.5 J. Using ½k(x₂ − x₁)² gives 0.5 J, which is wrong because the force is already 10 N at the start.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-work-energy-power-35","question":"A body of mass m moving with speed v makes a head-on elastic collision with a body of mass 2m at rest. The fraction of its kinetic energy transferred to the heavier body is:","options":["8/9","2/3","1/3","1/9"],"answer":0,"explanation":"Fraction transferred = 4m₁m₂/(m₁ + m₂)² = 4 × m × 2m/(3m)² = 8/9. The striking body keeps 1/9 (it rebounds at v/3).","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-work-energy-power-36","question":"A block is projected up a rough 30° incline with a speed of 10 m/s. The coefficient of friction is 1/(2√3) (g = 10 m/s²). The distance it moves up the incline before stopping is:","options":["40/3 m","20/3 m","10 m","5 m"],"answer":1,"explanation":"Retardation = g sin30° + μg cos30° = 5 + 2.5 = 7.5 m/s². Distance = v²/2a = 100/15 = 20/3 m. Ignoring friction gives 10 m.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-work-energy-power-37","question":"A 1000 kg car's engine delivers a constant power of 20 kW. When the car moves at 10 m/s against a resistive force of 1000 N, its acceleration is:","options":["3 m/s²","2 m/s²","0.5 m/s²","1 m/s²"],"answer":3,"explanation":"Driving force = P/v = 20000/10 = 2000 N; net force = 2000 − 1000 = 1000 N, so a = 1 m/s². 2 m/s² ignores the resistance.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-work-energy-power-38","question":"A ball is dropped from a height h onto a floor. The coefficient of restitution is 1/2. The total distance travelled by the ball before it comes to rest is:","options":["2h","4h/3","5h/3","3h/2"],"answer":2,"explanation":"Each rebound height is e² = 1/4 of the previous one. Distance = h + 2h(e² + e⁴ + …) = h + 2h(1/4)/(3/4) = h + 2h/3 = 5h/3.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-work-energy-power-39","question":"A 2 kg block is dropped from a height of 2 m above the top of a vertical spring of force constant 400 N/m (g = 10 m/s²). The maximum compression of the spring is:","options":["0.25 m","0.5 m","1 m","0.45 m"],"answer":1,"explanation":"Gravity does work through the fall and the compression: mg(h + x) = ½kx² → 20(2 + x) = 200x² → 10x² − x − 2 = 0 → x = 0.5 m. Ignoring the extra fall x gives √0.2 ≈ 0.45 m.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-work-energy-power-40","question":"A 20 g bullet moving horizontally at 300 m/s passes through a 1 kg block hanging at rest from a long string and emerges at 100 m/s (g = 10 m/s²). The height to which the block rises is:","options":["0.4 m","0.8 m","0.2 m","1.6 m"],"answer":1,"explanation":"Momentum given to the block = 0.02 × (300 − 100) = 4 kg m/s, so its speed = 4 m/s and h = v²/2g = 16/20 = 0.8 m. Energy is not conserved during the passage, so momentum must be used for that step.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-work-energy-power-41","question":"How many of the following statements are correct?\n(A) The work done by a conservative force around any closed path is zero.\n(B) The work done by static friction is always zero.\n(C) The kinetic energy of a system can change even when no external force acts on it.\n(D) A potential energy function can be defined for kinetic friction.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"A is correct. C is correct: internal forces can change the total KE, as in an explosion. B is wrong: static friction does work on a box riding on an accelerating truck. D is wrong: friction is non-conservative. So only two are correct.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-work-energy-power-42","question":"A force F = 2t newton (t in seconds) acts on a 1 kg body initially at rest. The instantaneous power delivered by the force at t = 2 s is:","options":["32 W","16 W","8 W","4 W"],"answer":1,"explanation":"a = 2t, so v = t² = 4 m/s at t = 2 s, when F = 4 N. P = Fv = 4 × 4 = 16 W.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-work-energy-power-43","question":"Blocks of masses m and 2m are connected by a light spring of force constant k on a smooth floor. The block of mass m is given a speed v₀ towards the other, both initially at rest with the spring relaxed. The maximum compression of the spring is:","options":["v₀√(2m/3k)","v₀√(m/3k)","v₀√(m/k)","v₀√(3m/2k)"],"answer":0,"explanation":"At maximum compression both move with the common velocity v₀/3. KE lost = ½mv₀² − ½(3m)(v₀/3)² = (1/3)mv₀² = ½kx², giving x = v₀√(2m/3k). v₀√(m/k) would hold only if the 2m block were fixed.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-work-energy-power-44","question":"Assertion (A): A body cannot have energy without having momentum.\nReason (R): The kinetic energy of a body is related to its momentum by K = p²/2m.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"R is true, but A is false: a body at rest can have potential energy (a raised stone or a compressed spring) with zero momentum. R concerns only kinetic energy.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-work-energy-power-45","question":"A bob hangs from a light string of length L. It is given a horizontal speed √(3gL) at the lowest point. The height above the lowest point at which the string becomes slack is:","options":["2L","5L/3","3L/2","4L/3"],"answer":3,"explanation":"At angle θ from the lowest point, v² = 3gL − 2gL(1 − cosθ) = gL + 2gL cosθ. Tension vanishes when v² = −gL cosθ, giving cosθ = −1/3. Height = L(1 − cosθ) = 4L/3. The bob cannot complete the circle, which would need 5gL.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "phy-work-energy-power-46", "question": "A porter carries a suitcase on his head and walks along a level road at constant speed. The work done by him against gravity is:", "options": ["positive", "negative", "zero", "equal to the weight × distance walked"], "answer": 2, "explanation": "The force he exerts against gravity is vertical while the displacement is horizontal, so W = Fs cos 90° = 0, though he certainly gets tired.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-work-energy-power-47", "question": "One kilowatt-hour (1 kWh) is equal to:", "options": ["3.6 × 10⁶ J", "3.6 × 10³ J", "1000 J", "3.6 × 10⁵ J"], "answer": 0, "explanation": "1 kWh = 1000 W × 3600 s = 3.6 × 10⁶ J. It is a unit of energy, not of power.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-work-energy-power-48", "question": "The speed of a 2 kg body increases from 2 m/s to 4 m/s. The net work done on it is:", "options": ["4 J", "16 J", "8 J", "12 J"], "answer": 3, "explanation": "By the work–energy theorem, W = ½ × 2 × (4² − 2²) = 12 J. 4 J uses ½m(Δv)², which is not the change in kinetic energy.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "phy-work-energy-power-49", "question": "A 10 kg bag is lifted vertically through 2 m at constant speed (g = 10 m/s²). The net work done on the bag by all the forces acting on it is:", "options": ["200 J", "zero", "−200 J", "400 J"], "answer": 1, "explanation": "At constant speed ΔKE = 0, so the net work is zero: the lifter does +200 J and gravity does −200 J. 200 J is the work done by the lifter alone.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-work-energy-power-50", "question": "A 1500 kg car climbs a road that rises 1 m for every 10 m travelled along it, at a constant 10 m/s. Neglecting friction, the power delivered by the engine is (g = 10 m/s²):", "options": ["150 kW", "15 kW", "1.5 kW", "7.5 kW"], "answer": 1, "explanation": "sin θ = 1/10, so the engine must supply mg sin θ = 1500 N. P = Fv = 1500 × 10 = 15000 W = 15 kW.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "phy-work-energy-power-51", "question": "A 2 kg body moving at 3 m/s and a 3 kg body moving at 2 m/s in the opposite direction approach each other. The velocity of their centre of mass is:", "options": ["2.4 m/s", "0.4 m/s", "1 m/s", "zero"], "answer": 3, "explanation": "v_cm = (2 × 3 + 3 × (−2))/5 = 0. The total momentum is zero, so the centre of mass stays at rest whatever the collision does.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "phy-work-energy-power-52", "question": "The potential energy of a particle moving along the x-axis is U = 5x² joule (x in metres). The force on it at x = 2 m is:", "options": ["20 N directed towards the origin", "20 N directed away from the origin", "10 N directed towards the origin", "40 N directed away from the origin"], "answer": 0, "explanation": "F = −dU/dx = −10x = −20 N at x = 2 m: magnitude 20 N, pointing in the −x direction, back towards the origin (a restoring force).", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "phy-work-energy-power-53", "question": "A force acting on a particle along the x-axis is 10 N from x = 0 to x = 2 m, and then decreases uniformly to zero at x = 6 m. The total work done by the force is:", "options": ["60 J", "20 J", "40 J", "30 J"], "answer": 2, "explanation": "Work = area under the F–x graph: rectangle 10 × 2 = 20 J plus triangle ½ × 4 × 10 = 20 J, total 40 J.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-work-energy-power-54", "question": "A 2 kg ball moving at 6 m/s collides head-on with a 4 kg ball at rest; the coefficient of restitution is 0.5. Their velocities after the collision are:", "options": ["2 m/s and 2 m/s", "−2 m/s and 4 m/s", "1 m/s and 2.5 m/s", "0 and 3 m/s"], "answer": 3, "explanation": "Momentum: 2v₁ + 4v₂ = 12. Restitution: v₂ − v₁ = 0.5 × 6 = 3. Solving: v₂ = 3 m/s and v₁ = 0. Equal velocities (2 m/s) would mean e = 0; −2 and 4 m/s would mean e = 1.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-work-energy-power-55", "question": "A motor pumps water from a well 20 m deep at 5 kg/s and delivers it at the top with a speed of 10 m/s. If the pump is 50% efficient, its power input is (g = 10 m/s²):", "options": ["1.25 kW", "2.5 kW", "2 kW", "1 kW"], "answer": 1, "explanation": "Useful power = (dm/dt)(gh + v²/2) = 5 × (200 + 50) = 1250 W. At 50% efficiency the input is 2500 W. 2 kW ignores the kinetic energy given to the water.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-work-energy-power-56", "question": "A 1 kg block moving at 3 m/s on a rough horizontal floor (μ = 0.5) hits a light spring of force constant 800 N/m (g = 10 m/s²). The maximum compression of the spring is:", "options": ["10.6 cm", "15 cm", "10 cm", "5 cm"], "answer": 2, "explanation": "½mv² = ½kx² + μmgx: 4.5 = 400x² + 5x, which x = 0.1 m satisfies (4 + 0.5 = 4.5). Without friction x would be √(9/800) ≈ 10.6 cm.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-work-energy-power-57", "question": "A 0.1 kg ball is thrown vertically upward at 20 m/s and rises to a maximum height of 15 m (g = 10 m/s²). The work done on it by air resistance during the ascent is:", "options": ["−5 J", "−15 J", "+5 J", "−20 J"], "answer": 0, "explanation": "Initial KE = ½ × 0.1 × 400 = 20 J; potential energy gained = 0.1 × 10 × 15 = 15 J. The missing 5 J was removed by air drag, so its work is −5 J.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "phy-work-energy-power-58", "question": "A ball moving at 5 m/s collides elastically and head-on with a massive wall that is moving towards the ball at 2 m/s. The speed of the ball after the collision is:", "options": ["5 m/s", "7 m/s", "9 m/s", "3 m/s"], "answer": 2, "explanation": "In the wall's frame the ball approaches at 7 m/s and rebounds at 7 m/s; back in the ground frame its speed is 7 + 2 = 9 m/s. 7 m/s forgets to add the wall's velocity back.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-work-energy-power-59", "question": "A 1 kg body falls freely from rest (g = 10 m/s²). The average power delivered by gravity during the first 2 s of the fall is:", "options": ["100 W", "200 W", "50 W", "400 W"], "answer": 0, "explanation": "In 2 s it falls 20 m, so W = 1 × 10 × 20 = 200 J and average power = 200/2 = 100 W. 200 W is the instantaneous power mgv at t = 2 s.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "phy-work-energy-power-60", "question": "A 2 kg block is gently placed on a horizontal conveyor belt that moves at a constant 4 m/s. The block slides until it moves with the belt. The total energy supplied by the motor driving the belt during this time is:", "options": ["16 J", "8 J", "64 J", "32 J"], "answer": 3, "explanation": "The block gains ½ × 2 × 4² = 16 J. During the slip the belt moves twice as far as the block, so the heat produced, f × (relative slip), is also 16 J. The motor supplies 16 + 16 = 32 J, whatever the coefficient of friction.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-work-energy-power-61", "question": "A bullet loses half of its speed after penetrating 3 cm into a wooden block. Assuming a constant resistive force, how much farther will it penetrate before stopping?", "options": ["3 cm", "1 cm", "1.5 cm", "6 cm"], "answer": 1, "explanation": "Halving the speed removes 3/4 of the KE in 3 cm, so 1/4 of the original KE is left, which needs one-third of that distance: 1 cm. 3 cm assumes the speed falls linearly with distance.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "phy-work-energy-power-62", "question": "How many of the following statements are correct?\n(A) The work done by static friction on a body is always zero.\n(B) The total work done by a pair of kinetic friction forces between two surfaces sliding over each other is always negative.\n(C) Mechanical energy is conserved in an inelastic collision.\n(D) The total linear momentum of an isolated system is conserved in every collision.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "B and D are correct. A is wrong: static friction does positive work on a box carried along by an accelerating truck. C is wrong: in an inelastic collision some kinetic energy turns into heat, sound or deformation. Two are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-work-energy-power-63", "question": "A 2 kg block with a smooth quarter-circular groove of radius 1.8 m rests on a smooth floor. A 1 kg particle is released from the top of the groove (g = 10 m/s²). The speed of the particle relative to the ground when it leaves the groove at the bottom is:", "options": ["6 m/s", "2√6 m/s ≈ 4.9 m/s", "√6 m/s ≈ 2.4 m/s", "3√2 m/s ≈ 4.2 m/s"], "answer": 1, "explanation": "Horizontal momentum: 1·v = 2·V, so V = v/2. Energy: ½v² + ½ × 2 × (v/2)² = 1 × 10 × 1.8 = 18, so ¾v² = 18, v² = 24, v = 2√6 m/s. 6 m/s = √(2gR) would apply only if the block were fixed.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-work-energy-power-64", "question": "A shell is fired at 20 m/s at 45° above level ground (g = 10 m/s²). At the highest point it bursts into two equal halves; one half has zero velocity just after the burst and falls vertically. The other half lands at a distance from the gun of:", "options": ["40 m", "80 m", "50 m", "60 m"], "answer": 3, "explanation": "Normal range R = u²/g = 40 m, so the burst occurs at x = 20 m. Momentum conservation doubles the horizontal velocity of the moving half, so in the equal time of descent it travels 2 × 20 = 40 m more: lands at 60 m.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-work-energy-power-65", "question": "A car's maximum speed on a level road is 30 m/s when its engine delivers power P. If the resistive force is proportional to the square of the speed, the power needed for a maximum speed of 60 m/s is:", "options": ["8P", "4P", "2P", "16P"], "answer": 0, "explanation": "At top speed the driving force equals the resistance kv², so P = kv² × v = kv³. Doubling v needs 2³ = 8 times the power. 4P forgets that power is force × velocity.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-work-energy-power-66", "question": "A bob hangs from a light string that can withstand a maximum tension of twice the bob's weight. The bob is pulled aside until the string is horizontal and then released. The string breaks when it makes an angle with the vertical of:", "options": ["60°", "30°", "cos⁻¹(2/3) ≈ 48°", "it never breaks"], "answer": 2, "explanation": "At angle θ from the vertical, v² = 2gL cos θ and T = mg cos θ + mv²/L = 3mg cos θ. T reaches 2mg when cos θ = 2/3, θ ≈ 48°, before the bob reaches the bottom (where T would be 3mg).", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-work-energy-power-67", "question": "Assertion (A): A spring has more potential energy when stretched by a length x than when compressed by the same length x.\nReason (R): The potential energy of a spring is ½kx², where x is the change from its natural length.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "R is true, and it shows A is false: ½kx² depends only on x², so equal stretching and compression store equal energy.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-work-energy-power-68", "question": "Match the collision (List I) with its coefficient of restitution e (List II).\nList I: (P) perfectly elastic collision; (Q) perfectly inelastic collision; (R) a ball dropped from height h rebounds to h/4; (S) a ball dropped from height h rebounds to h/9.\nList II: (1) 1/3; (2) 0; (3) 1/2; (4) 1.", "options": ["P-4, Q-2, R-1, S-3", "P-2, Q-4, R-3, S-1", "P-4, Q-1, R-3, S-2", "P-4, Q-2, R-3, S-1"], "answer": 3, "explanation": "Elastic: e = 1; perfectly inelastic: e = 0. For a ball bouncing on the floor e = √(h′/h): √(1/4) = 1/2 and √(1/9) = 1/3. So P-4, Q-2, R-3, S-1.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-work-energy-power-69", "question": "A small ball is fixed to one end of a light rigid rod of length 0.9 m that can rotate freely in a vertical plane about its other end (g = 10 m/s²). The minimum speed at the lowest point for the ball to complete the circle is:", "options": ["√45 m/s ≈ 6.7 m/s", "6 m/s", "3 m/s", "√27 m/s ≈ 5.2 m/s"], "answer": 1, "explanation": "A rigid rod can push as well as pull, so the ball only has to reach the top with speed just above zero: v² = 2g(2L) = 4 × 10 × 0.9 = 36, v = 6 m/s. √(5gL) ≈ 6.7 m/s is the value for a string, which goes slack if the top speed is below √(gL).", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-work-energy-power-70", "question": "From a uniform circular disc of radius R, a circular disc of radius R/2 is cut out such that its rim touches the rim of the original disc. The centre of mass of the remaining part is shifted from the original centre by:", "options": ["R/4", "R/3", "R/6", "R/2"], "answer": 2, "explanation": "The cut piece has 1/4 of the mass with its centre at R/2 from O. Remaining COM: x = −(M/4)(R/2)/(3M/4) = −R/6, on the side opposite the hole.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id":"phy-work-energy-power-71","question":"A 0.5 kg ball is thrown at 20 m/s at 30° above the horizontal (g = 10 m/s²). The work done by gravity on the ball from the moment of projection until it reaches its highest point is:","options":["−25 J","+25 J","−100 J","0"],"answer":0,"explanation":"Maximum height H = (20 sin 30°)²/(2g) = 100/20 = 5 m. Gravity acts against the upward displacement: W = −mgH = −0.5 × 10 × 5 = −25 J. −100 J would be the whole initial kinetic energy, but the horizontal part of the motion keeps its kinetic energy.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-work-energy-power-72","question":"Two springs of force constants 100 N/m and 300 N/m are joined in series and stretched by a force of 30 N. The ratio of the energy stored in the softer spring to that stored in the stiffer spring is:","options":["1 : 3","3 : 1","1 : 1","9 : 1"],"answer":1,"explanation":"In series both carry the same force F, so U = F²/2k: U₁ = 900/200 = 4.5 J and U₂ = 900/600 = 1.5 J, a ratio of 3 : 1. The ratio 1 : 3 comes from using U = ½kx² as if both springs had the same extension.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-work-energy-power-73","question":"The kinetic energy of a body increases by 44%. Its linear momentum increases by:","options":["44%","22%","20%","12%"],"answer":2,"explanation":"p = √(2mK), so p′/p = √1.44 = 1.2: an increase of 20%. 22% uses the small-change approximation (half of 44%), which is not valid for so large a change.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-work-energy-power-74","question":"A ball is dropped from a height of 5 m onto a floor with which its coefficient of restitution is 1/2 (g = 10 m/s²). The total time from release until it stops bouncing is:","options":["2 s","4 s","1.5 s","3 s"],"answer":3,"explanation":"The first fall takes t₀ = √(2h/g) = 1 s. Each bounce has speed reduced by e, and the round trip after the nth impact lasts 2eⁿt₀. Total = t₀ + 2t₀(e + e² + …) = t₀(1 + e)/(1 − e) = 1 × 1.5/0.5 = 3 s.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-work-energy-power-75","question":"From a uniform square plate of side 2a, a square of side a is cut away from one corner. The centre of mass of the remaining plate is shifted from the centre of the original square by:","options":["a√2/6, away from the cut corner","a/6, away from the cut corner","a√2/3, away from the cut corner","a√2/4, towards the cut corner"],"answer":0,"explanation":"The removed piece has 1/4 of the mass and its centre is at (a/2, a/2) from the centre. The remainder (3/4 of the mass) shifts the other way by (1/4)(a/2)/(3/4) = a/6 along each axis, i.e. a√2/6 along the diagonal. a/6 is only one component.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-work-energy-power-76","question":"Blocks of 1 kg and 3 kg, on a smooth floor, are pushed together against a light spring between them (not attached), storing 8 J. When released, the kinetic energy finally gained by the 1 kg block is:","options":["2 J","6 J","8 J","4 J"],"answer":1,"explanation":"Total momentum stays zero, so p is the same for both and K = p²/2m: K₁/K₃ = 3/1. With K₁ + K₃ = 8 J, K₁ = 6 J and K₃ = 2 J. The lighter block takes the larger share.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-work-energy-power-77","question":"A 0.5 kg bob hangs from a 2 m string. A horizontal force is applied to it, slowly increasing, so that the bob moves quasi-statically until the string makes 60° with the vertical (g = 10 m/s²). The work done by the horizontal force is:","options":["8.7 J","15 J","5 J","10 J"],"answer":2,"explanation":"Moving slowly means no kinetic energy is gained, so the force's work equals the rise in potential energy: mgL(1 − cos 60°) = 0.5 × 10 × 2 × 0.5 = 5 J. Multiplying the final force mg tan 60° by the horizontal displacement L sin 60° gives 15 J, but the force is not constant.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-work-energy-power-78","question":"A ball strikes a smooth horizontal floor at 45° to it, and the coefficient of restitution is 1/2. The fraction of its kinetic energy lost in the impact is:","options":["3/4","1/2","1/4","3/8"],"answer":3,"explanation":"On a smooth floor the horizontal component v/√2 is unchanged and the vertical component v/√2 becomes v/(2√2). New K ∝ v²/2 + v²/8 = 5v²/8, so the fraction lost is 3/8. 3/4 is the loss if the whole velocity were normal to the floor.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-work-energy-power-79","question":"A 2 kg ball moving at 5 m/s collides head-on with a 3 kg ball at rest, the coefficient of restitution being 0.5. The kinetic energy lost in the collision is:","options":["11.25 J","7.5 J","3.75 J","15 J"],"answer":0,"explanation":"ΔK = ½ μ(1 − e²)u² with reduced mass μ = (2 × 3)/5 = 1.2 kg: ΔK = 0.5 × 1.2 × 0.75 × 25 = 11.25 J. (Check: after the collision the speeds are 0.5 m/s and 3 m/s, so K drops from 25 J to 13.75 J.) 15 J is the loss for a perfectly inelastic collision (e = 0).","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "phy-work-energy-power-80", "question": "Four balls of masses m, m/2, m/4 and m/8 lie in a straight line on a smooth floor. The first ball is given a speed v towards the others, and all collisions are elastic and head-on. The speed finally acquired by the fourth ball is:", "options": ["8v", "64v/27", "2v", "27v/8"], "answer": 1, "explanation": "For an elastic collision with a body at rest, the struck ball gets 2m₁v/(m₁ + m₂). With m₂ = m₁/2, that is (4/3)v each time, so after three collisions v₄ = (4/3)³v = 64v/27. 2v would be right only if each target were much lighter than the striker.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-work-energy-power-81", "question": "A 1 kg block on a horizontal floor is attached to a spring of force constant 100 N/m whose other end is fixed. The coefficient of kinetic friction is 0.2 and of static friction 0.3. The block is pulled 10 cm from the natural length and released (g = 10 m/s²). The total distance it travels before coming to rest permanently is:", "options": ["25 cm", "20 cm", "24 cm", "16 cm"], "answer": 2, "explanation": "Each half-swing ends 2μ_k mg/k = 4 cm closer to the natural length: +10 → −6 → +2 cm. At +2 cm the spring force (2 N) is below the static limit (3 N), so it stays there. Distance = 16 + 8 = 24 cm; check: ½ × 100 × (0.10² − 0.02²) = 0.48 J = 2 N × 0.24 m. 25 cm assumes it stops at the natural length.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"phy-work-energy-power-82","question":"A smooth sphere moving at 10 m/s strikes an identical smooth sphere at rest. At impact the line joining their centres makes 60° with the direction of motion of the first sphere, and the coefficient of restitution is 1/2. The speed of the second sphere after the collision is:","options":["7.5 m/s","5 m/s","2.5 m/s","3.75 m/s"],"answer":3,"explanation":"Only the component along the line of centres, 10 cos 60° = 5 m/s, takes part; the perpendicular component (5√3 m/s) of the first sphere is unchanged. Along the line: v₂ = (1 + e)u/2 = 1.5 × 5/2 = 3.75 m/s. 5 m/s is the elastic (e = 1) value.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-work-energy-power-83", "question": "The potential energy of a diatomic molecule as a function of the separation x of its atoms is U(x) = a/x¹² − b/x⁶, with a and b positive constants. The energy needed to separate the atoms completely, starting from the equilibrium position at rest, is:", "options": ["b²/(4a)", "b²/(2a)", "b/(2a)", "a²/(4b)"], "answer": 0, "explanation": "dU/dx = 0 gives x⁶ = 2a/b. Then U(eq) = a(b/2a)² − b(b/2a) = b²/4a − b²/2a = −b²/(4a). Since U(∞) = 0, the dissociation energy is b²/(4a). b²/(2a) is just the size of the attractive term at equilibrium.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"phy-work-energy-power-84","question":"A force F = (y i + 2x j) N acts on a particle that moves in the xy-plane from (0, 0) to (2 m, 2 m) along the straight line y = x. The work done by the force is:","options":["8 J","6 J","4 J","12 J"],"answer":1,"explanation":"Along y = x: W = ∫(y dx + 2x dy) = ∫₀² (x + 2x) dx = 3x²/2 from 0 to 2 = 6 J. The force is not conservative (∂F_x/∂y = 1 ≠ ∂F_y/∂x = 2), so the work depends on the path: along the x-axis and then up it is 8 J, along the y-axis and then across it is 4 J.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-work-energy-power-85","question":"A small particle is placed at the top of a smooth fixed sphere of radius R and given a horizontal speed √(gR/2). It slides down the outside of the sphere. It leaves the surface at a height above the centre of the sphere of:","options":["2R/3","R/2","5R/6","3R/4"],"answer":2,"explanation":"At angle θ from the top: v² = gR/2 + 2gR(1 − cos θ), and it leaves when N = 0, i.e. v² = gR cos θ. So 3gR cos θ = 2gR + gR/2, giving cos θ = 5/6, height 5R/6. 2R/3 is the answer for a start from rest.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-work-energy-power-86", "question": "A 1 kg block moving at 6 m/s on a smooth floor slides onto the smoothly curved surface of a 2 kg wedge that is free to move on the floor (g = 10 m/s²). The greatest height the block reaches on the wedge is:", "options": ["1.8 m", "0.6 m", "2.4 m", "1.2 m"], "answer": 3, "explanation": "At the highest point the block and the wedge share a common horizontal velocity: 1 × 6 = 3v, so v = 2 m/s. Energy: ½ × 1 × 36 = ½ × 3 × 4 + 10h, so h = (18 − 6)/10 = 1.2 m. 1.8 m (= v²/2g) treats the wedge as fixed.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-work-energy-power-87", "question": "How many of the following statements are correct?\n(A) When two bodies slide over each other, the total work done by the pair of kinetic friction forces on them is always negative.\n(B) Internal forces can change the total kinetic energy of a system.\n(C) The work–energy theorem holds in a non-inertial frame provided the work done by the pseudo forces is included.\n(D) At a position of stable equilibrium the potential energy is a maximum.", "options": ["Only one", "Only three", "Only two", "All four"], "answer": 1, "explanation": "A: the pair's total work is −f × (relative sliding distance), always negative. B: a spring pushing two blocks apart, or an explosion, raises K. C: correct with pseudo forces. D is wrong: stable equilibrium is a minimum of potential energy.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-work-energy-power-88", "question": "Sand drops vertically at 2 kg/s onto a horizontal conveyor belt moving at a constant 3 m/s. The rate at which heat is produced by friction between the sand and the belt is:", "options": ["9 W", "18 W", "6 W", "0"], "answer": 0, "explanation": "The force needed to keep the belt moving is (dm/dt)v = 6 N, so the motor supplies 6 × 3 = 18 W. The sand gains kinetic energy at only ½(dm/dt)v² = 9 W; the other 9 W is dissipated as heat while each grain slides before matching the belt's speed. 18 W is the total power.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"phy-work-energy-power-89","question":"A 1000 kg car's engine delivers a constant power of 20 kW. Neglecting all resistance, the distance it covers while its speed rises from 10 m/s to 20 m/s is about:","options":["75 m","117 m","233 m","150 m"],"answer":1,"explanation":"P = mv²(dv/dx), so dx = (m/P)v² dv and x = m(v₂³ − v₁³)/(3P) = 1000 × 7000/60 000 ≈ 116.7 m. (The time is m(v₂² − v₁²)/(2P) = 7.5 s.) 75 m multiplies 7.5 s by the starting speed; 150 m uses the average speed 15 m/s as if the acceleration were uniform.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-work-energy-power-90", "question": "Assertion (A): In an elastic collision between two bodies, the total kinetic energy is conserved at every instant during the collision.\nReason (R): The total linear momentum of the two bodies is conserved throughout the collision.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is false but R is true", "A is true but R is false"], "answer": 2, "explanation": "During contact some kinetic energy is temporarily stored as elastic deformation energy (at maximum compression the bodies move together), and it is all returned only at the end. Momentum, however, is conserved at every instant, because the contact forces are internal.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-work-energy-power-91", "question": "A 2 kg body, initially at rest at x = 0, moves along the x-axis under a single force F = (20 − 5x) N, with x in metres. The greatest speed it attains is:", "options": ["√30 m/s", "√10 m/s", "2√10 m/s", "2√5 m/s"], "answer": 2, "explanation": "The speed is greatest where F = 0, at x = 4 m. Work up to there = ∫₀⁴ (20 − 5x) dx = 80 − 40 = 40 J = ½ × 2 × v², so v = √40 = 2√10 ≈ 6.3 m/s. √30 m/s is its speed at x = 6 m, after the force has turned negative and slowed it.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-work-energy-power-92","question":"A small ball of mass m rests on top of a large ball of mass 3m, with a tiny gap between them, and the pair is dropped from a height h onto a hard floor. All collisions are elastic and the balls move vertically. The small ball rebounds to a height (measured from its position at the moment of the collision) of:","options":["3h","9h","2h","4h"],"answer":3,"explanation":"Both reach the floor at speed v = √(2gh). The big ball rebounds at v upward and meets the small ball moving down at v. Elastic collision: v′ = [(M − m)v + 2Mv]/(M + m) = (2m·v + 6m·v)/(4m) = 2v upward, so the rebound height is (2v)²/2g = 4h. 9h is the limit for M ≫ m (3v).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "phy-work-energy-power-93", "question": "How many of the following statements about the centre of mass are correct?\n(A) The centre of mass of a body can lie at a point where there is no matter.\n(B) If no external force acts on a system, its centre of mass keeps a constant velocity even if the system explodes.\n(C) The centre of mass of a thin uniform semicircular ring of radius R is 4R/(3π) from the centre.\n(D) The centre of mass of two particles divides the line joining them in the inverse ratio of their masses.", "options": ["Only one", "Only two", "All four", "Only three"], "answer": 3, "explanation": "A (for example a ring), B and D are correct. C is wrong: for a semicircular ring it is 2R/π; 4R/(3π) is for a semicircular disc.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-work-energy-power-94","question":"A 1 kg particle moving east at 6 m/s collides with a 2 kg particle moving north at 3 m/s, and they stick together. The kinetic energy lost in the collision is:","options":["15 J","12 J","27 J","9 J"],"answer":0,"explanation":"Momentum: (6, 6) kg m/s shared by 3 kg gives a velocity (2, 2) m/s, speed 2√2 m/s. K before = ½(1)(36) + ½(2)(9) = 27 J; after = ½(3)(8) = 12 J. Loss = 15 J. 12 J is the final kinetic energy, not the loss.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-work-energy-power-95", "question": "A simple pendulum of length 1 m is released from rest with its string horizontal. A peg is fixed a distance d vertically below the point of suspension, so that the string catches on it and the bob swings round the peg. The least d for which the bob completes a full circle about the peg is:", "options": ["0.4 m", "0.6 m", "0.8 m", "0.5 m"], "answer": 1, "explanation": "At the lowest point v² = 2gL. The bob then moves in a circle of radius r = L − d about the peg, which needs v² ≥ 5gr at that point: 2gL ≥ 5g(L − d), so d ≥ 3L/5 = 0.6 m. 0.4 m is the radius of the smaller circle, not the peg's depth.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-work-energy-power-96","question":"A small block slides down the smooth inclined face of a wedge that rests on a smooth horizontal floor, so the wedge recoils. Which statement about the normal force exerted by the wedge on the block is correct?","options":["Its work on the block is equal to its work on the wedge","It does no work on the block because it is perpendicular to the incline","It does positive work on the block","It does negative work on the block"],"answer":3,"explanation":"The normal force is perpendicular to the block's velocity RELATIVE to the wedge, but the wedge itself moves, so in the ground frame it is not perpendicular to the block's velocity. The wedge gains kinetic energy only from the block's normal force; since total mechanical energy is conserved, the block's normal force does equal and opposite (negative) work on the block.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-work-energy-power-97","question":"A spring stores 8 J when stretched by 4 cm. It is cut into two equal halves, and ONE half is stretched by 4 cm. The energy stored in it is:","options":["4 J","8 J","16 J","32 J"],"answer":2,"explanation":"Cutting a spring in half doubles its force constant (k ∝ 1/length). The energy ½k′x² at the same 4 cm extension therefore doubles to 16 J.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-work-energy-power-98","question":"A simple pendulum of length 1 m is released from rest with the string horizontal. A thin peg is fixed vertically below the point of suspension. For the bob to swing in a complete circle around the peg once the string catches it, the minimum distance of the peg below the point of suspension is:","options":["0.4 m","0.6 m","0.5 m","0.8 m"],"answer":1,"explanation":"At the lowest point v² = 2gL. Around the peg the radius is r = L − d, and a complete circle needs v² ≥ 5gr at the bottom. So 2gL ≥ 5g(L − d), giving d ≥ 3L/5 = 0.6 m.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-work-energy-power-99","question":"A 1 kg ball moving on a smooth straight groove is to transfer as much kinetic energy as possible to a 9 kg ball at rest further along, through an intermediate ball placed between them. All collisions are elastic and head-on. The best mass for the intermediate ball is:","options":["3 kg","5 kg","9 kg","1 kg"],"answer":0,"explanation":"The final speed of the 9 kg ball is u·[2m₁/(m₁ + m)]·[2m/(m + m₃)], which is maximised when m = √(m₁m₃). Here m = √(1 × 9) = 3 kg, the geometric (not arithmetic) mean.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-work-energy-power-100","question":"A 1 kg bob hangs at rest on a light string of length 0.8 m. A 2 kg ball moving horizontally at 6 m/s strikes it head-on elastically (g = 10 m/s²). The tension in the string when the bob is at the top of its circular path is:","options":["30 N","40 N","50 N","20 N"],"answer":0,"explanation":"Elastic collision: v_bob = 2 × 2 × 6/(2 + 1) = 8 m/s, which exceeds √(5gL) = √40, so it completes the circle. At the top v² = 64 − 4gL = 32, and T + mg = mv²/L gives T = 32/0.8 − 10 = 30 N.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-work-energy-power-101","question":"A block slides at 2 m/s onto a rough horizontal strip whose coefficient of friction increases with distance as μ = 0.1x (x in metres from the start of the strip). Taking g = 10 m/s², the block stops after sliding:","options":["1 m","4 m","√2 m","2 m"],"answer":3,"explanation":"Work–energy: ½mv₀² = ∫₀ˣ μmg dx = mg(0.1)x²/2 = m·x²/2. So x² = v₀² = 4 and x = 2 m, independent of the mass.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-work-energy-power-102","question":"A 1 kg particle moves in the xy-plane in a potential energy field U = (3x + 4y) joule (x, y in metres). It is released from rest at (6 m, 8 m). It reaches the x-axis after a time t with speed v, where:","options":["t = √2 s, v = 10 m/s","t = 2 s, v = 5 m/s","t = 2 s, v = 10 m/s","t = 4 s, v = 20 m/s"],"answer":2,"explanation":"F = −∇U = (−3, −4) N, so the acceleration is constant: 5 m/s² towards the origin. The y-motion gives 8 = ½ × 4 × t², so t = 2 s (it actually passes through the origin). Speed = 5 × 2 = 10 m/s, consistent with ΔU = 50 J = ½mv².","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-work-energy-power-103","question":"A 3 kg ball moving at 4 m/s collides head-on with a 1 kg ball moving at 4 m/s in the opposite direction. The coefficient of restitution is 0.5. The kinetic energy lost in the collision is:","options":["24 J","18 J","6 J","13.5 J"],"answer":1,"explanation":"The loss depends only on the reduced mass μ = m₁m₂/(m₁ + m₂) = 0.75 kg and the approach speed 8 m/s: ΔK = ½μu²(1 − e²) = ½ × 0.75 × 64 × 0.75 = 18 J. 24 J would be the loss for a perfectly inelastic collision.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-work-energy-power-104","question":"A 100 g bullet moving at 100 m/s embeds itself in a 900 g block resting on a smooth floor and attached to a fixed wall by a light spring of force constant 1000 N/m. The maximum compression of the spring is about:","options":["1 m","0.316 m","0.1 m","3.16 m"],"answer":1,"explanation":"During the very short impact only momentum is conserved: v = 0.1 × 100/1 = 10 m/s. Afterwards energy is conserved: ½ × 1 × 10² = ½ × 1000 × x², so x = √0.1 ≈ 0.316 m. Using the bullet's original kinetic energy (500 J) ignores the 450 J lost in the embedding.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-work-energy-power-105","question":"A 0.5 kg bead slides on a smooth vertical circular wire of radius 0.5 m. A light spring of natural length 0.5 m and force constant 10 N/m joins the bead to the topmost point of the wire. The bead is released from rest where the spring is unstretched and slides to the lowest point (g = 10 m/s²). The force exerted by the wire on the bead there is:","options":["10 N, upward","5 N, upward","zero","15 N, upward"],"answer":0,"explanation":"Unstretched means the chord from the top is R, so the bead starts R/2 above the centre and falls 1.5R = 0.75 m. At the bottom the spring (length 2R) is stretched by 0.5 m: ½mv² = 3.75 − 1.25 = 2.5 J, v² = 10. Radially: N + kR − mg = mv²/R gives N + 5 − 5 = 10, so N = 10 N upward.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-work-energy-power-106","question":"Water falls from a height of 50 m at a rate of 2 m³/s onto a turbine that converts 60% of the energy into electrical power (g = 10 m/s², density 1000 kg/m³). The electrical power output is:","options":["1200 kW","1000 kW","60 kW","600 kW"],"answer":3,"explanation":"Mass per second = 2000 kg/s, so the gravitational power is ṁgh = 2000 × 10 × 50 = 1 MW. With 60% efficiency the output is 600 kW.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-work-energy-power-107","question":"A fan pushes air (density 1.2 kg/m³) through a circular opening of area 0.5 m² at a uniform speed of 10 m/s, starting from still air. The minimum power needed to keep this air stream going is:","options":["60 W","600 W","300 W","30 W"],"answer":2,"explanation":"Mass flow = ρAv = 6 kg/s. Each kilogram gains ½v² = 50 J, so the power is ½ρAv³ = 6 × 50 = 300 W. Note the v³ dependence: doubling the speed needs eight times the power.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-work-energy-power-108","question":"A 1 kg block is set sliding at 6 m/s on top of a long 2 kg plank that lies on a smooth floor. The coefficient of friction between block and plank is 0.3 (g = 10 m/s²). How far does the block slide RELATIVE TO THE PLANK before sliding stops?","options":["2 m","6 m","4 m","12 m"],"answer":2,"explanation":"Momentum conservation gives the common speed 6/3 = 2 m/s. Kinetic energy lost = 18 − 6 = 12 J, which equals the heat μmg × (relative sliding distance) = 3 × d. So d = 4 m.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-work-energy-power-109","question":"A 2 kg ball moving on a smooth horizontal surface collides elastically (not necessarily head-on) with a 1 kg ball at rest. The largest possible angle through which the 2 kg ball can be deflected is:","options":["60°","30°","90°","45°"],"answer":1,"explanation":"For an elastic collision of a heavier mass M with a lighter one m at rest, the maximum deflection of M satisfies sin θ_max = m/M (from the velocity-space circle in the CM frame). Here sin θ_max = 1/2, so θ_max = 30°. Only equal masses can reach 90° separation.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-work-energy-power-110","question":"A 50 kg man stands on a 100 kg cart at rest on a smooth level track. He jumps off horizontally along the track with a speed of 6 m/s RELATIVE TO THE CART. The work done by his muscles is:","options":["600 J","900 J","400 J","1200 J"],"answer":0,"explanation":"Momentum: 50v_m = 100v_c with v_m + v_c = 6, so v_m = 4 m/s and v_c = 2 m/s. Work by the muscles = total kinetic energy produced = ½ × 50 × 16 + ½ × 100 × 4 = 400 + 200 = 600 J (equivalently ½μv_rel² with μ = 100/3 kg).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-work-energy-power-111","question":"A 1 g raindrop falls from rest through 1 km and reaches the ground at its terminal speed of 10 m/s (g = 10 m/s²). The total work done on it by air resistance is:","options":["−0.05 J","−10 J","+9.95 J","−9.95 J"],"answer":3,"explanation":"Work–energy: W_g + W_air = ΔK. W_g = mgh = 10⁻³ × 10 × 1000 = 10 J and ΔK = ½ × 10⁻³ × 100 = 0.05 J. So W_air = 0.05 − 10 = −9.95 J: nearly all the gravitational work is dissipated.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-work-energy-power-112","question":"Block A (1 kg) moving at 4 m/s on a smooth floor hits a light spring attached to block B (3 kg), which is at rest. The maximum energy stored in the spring, and A's velocity after the blocks separate, are:","options":["2 J; A moves forward at 1 m/s","8 J; A moves back at 2 m/s","6 J; A comes to rest","6 J; A moves back at 2 m/s"],"answer":3,"explanation":"At maximum compression both move at the common speed 1 m/s, so U_max = 8 − ½ × 4 × 1² = 6 J (= ½μu² with μ = 0.75 kg). The spring interaction is elastic, so finally v_A = (1 − 3)/(1 + 3) × 4 = −2 m/s: A rebounds at 2 m/s while B moves on at 2 m/s.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-work-energy-power-113","question":"A particle moves along a quarter of a circle of radius 2 m centred at the origin, from (2 m, 0) to (0, 2 m), while one of the forces acting on it is a constant F = 10 î N. The work done by this force is:","options":["10π J","+20 J","−20 J","zero"],"answer":2,"explanation":"A constant force is conservative, so its work depends only on the displacement: W = F·Δr = 10î·(−2î + 2ĵ) = −20 J. The length of the curved path (π m) is irrelevant.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-work-energy-power-114","question":"A force F = (−y î + x ĵ) newton (x, y in metres) acts on a particle that goes once anticlockwise round the circle x² + y² = 1 m². The work done by F is:","options":["zero, since the path is closed","2π J","π J","4π J"],"answer":1,"explanation":"On the circle, F is tangential (along the direction of anticlockwise motion) with magnitude r = 1 N. W = F × circumference = 1 × 2π = 2π J. A non-zero work round a closed loop shows the force is non-conservative.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-work-energy-power-115","question":"A ball dropped from rest bounces on a hard floor. The time between its first and second impacts is 2 s, and between its second and third impacts is 1.6 s (g = 10 m/s²). The height from which it was dropped is about:","options":["7.8 m","5 m","12.5 m","3.2 m"],"answer":0,"explanation":"Successive flight times are in the ratio e, so e = 1.6/2 = 0.8. The first rebound speed satisfies 2(ev₀)/g = 2 s, so ev₀ = 10 m/s and v₀ = 12.5 m/s. Height = v₀²/2g = 156.25/20 ≈ 7.8 m.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-work-energy-power-116","question":"A 0.2 kg block is released from rest on a smooth track at a height of 3 m above the bottom of a vertical circular loop of radius 1 m, which it enters at the bottom (g = 10 m/s²). The normal force on the block at the top of the loop is:","options":["2 N","zero","4 N","6 N"],"answer":0,"explanation":"Energy: v_top² = 2g(H − 2R) = 2 × 10 × 1 = 20 m²/s². At the top, N + mg = mv²/R = 0.2 × 20 = 4 N, so N = 2 N (= mg here). The block would just make it with H = 2.5R.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-work-energy-power-117","question":"A truck and a scooter have the same kinetic energy. Which statement about their linear momenta is correct?","options":["Momentum cannot be compared without knowing their speeds","The scooter has the larger momentum","Their momenta are equal","The truck has the larger momentum"],"answer":3,"explanation":"p = √(2mK). For equal K, the momentum grows as √m, so the heavier truck has the larger momentum (and hence needs a larger impulse to stop).","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-work-energy-power-118","question":"A block attached to a spring (k = 500 N/m) is moved slowly from a position where the spring is compressed by 2 cm to one where it is stretched by 2 cm. The work done by the spring force during this displacement is:","options":["−0.2 J","0.2 J","zero","0.1 J"],"answer":2,"explanation":"The spring force is conservative, so its work is U_initial − U_final = ½k(0.02)² − ½k(0.02)² = 0. It does +0.1 J while relaxing to natural length and −0.1 J while being stretched.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-work-energy-power-119","question":"A small block at the bottom of a smooth vertical circular track of radius 0.9 m (moving on the inside) is given a horizontal speed √(3gR). It loses contact with the track at a height above the bottom of (g = 10 m/s²):","options":["0.9 m","1.2 m","1.35 m","1.5 m"],"answer":1,"explanation":"At height R(1 + sin φ), v² = 3gR − 2gR(1 + sin φ) = gR(1 − 2 sin φ). Contact is lost when N = 0, i.e. v² = gR sin φ. So 1 − 2 sin φ = sin φ, sin φ = 1/3, and the height is R(4/3) = 1.2 m.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-work-energy-power-120","question":"A crate is dragged at constant speed up a rough plane inclined at 37° (tan 37° = 0.75) by a force parallel to the plane; μ = 0.25. The efficiency of the incline as a machine (useful work in raising the crate ÷ total work done) is:","options":["25%","75%","60%","80%"],"answer":1,"explanation":"Per metre along the slope: useful work = mg sin θ, total = mg(sin θ + μ cos θ). Efficiency = tan θ/(tan θ + μ) = 0.75/1.00 = 75%.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-work-energy-power-121","question":"Blocks of 2 kg and 4 kg lie on a rough floor (μ = 0.5, g = 10 m/s²), joined by a light spring at its natural length. A CONSTANT horizontal force F is applied to the 2 kg block, pulling it away from the other. The minimum F that will just make the 4 kg block move is:","options":["20 N","30 N","10 N","40 N"],"answer":0,"explanation":"The 4 kg block moves when the spring force reaches μm₂g = 20 N, i.e. at extension x = 20/k. The 2 kg block need only just reach that extension (with zero speed): Fx − μm₁gx = ½kx². Hence F = μm₁g + kx/2 = 10 + 10 = 20 N = μg(m₁ + m₂/2), not the 30 N needed under a static analysis.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-work-energy-power-122","question":"A ball is thrown at 20 m/s at 45° above level ground towards a smooth vertical wall 15 m away (g = 10 m/s²). It hits the wall and bounces back, landing exactly at the point of projection. The coefficient of restitution between ball and wall is:","options":["0.5","0.375","0.8","0.6"],"answer":3,"explanation":"The smooth wall changes only the horizontal velocity (to e times its value), so the total flight time is unchanged: the range without the wall would be 40 m. After hitting the wall, the ball would have covered the remaining 25 m horizontally, but at e times the speed it covers 25e. For a return to the start, 25e = 15, so e = 0.6.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-work-energy-power-123","question":"A 3 kg shell at rest explodes into two fragments of 1 kg and 2 kg, releasing 300 J of kinetic energy. The speeds of the 1 kg and 2 kg fragments are:","options":["√300 m/s and √150 m/s","10 m/s and 20 m/s","20 m/s and 10 m/s","15 m/s and 7.5 m/s"],"answer":2,"explanation":"The fragments have equal and opposite momenta p. Total KE = p²/2 × (1/1 + 1/2) = 0.75p² = 300 J, so p = 20 kg m/s. Speeds: 20/1 = 20 m/s and 20/2 = 10 m/s; the lighter piece carries two-thirds of the energy.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-work-energy-power-124","question":"A 2 kg ball moving at 5 m/s approaches a 3 kg ball at rest on a smooth floor. The maximum kinetic energy that can possibly be converted into heat and deformation in their collision is:","options":["10 J","25 J","15 J","12.5 J"],"answer":2,"explanation":"Momentum conservation means the KE of the centre of mass, P²/2M = 10²/(2 × 5) = 10 J, must remain. Total KE = 25 J, so at most 25 − 10 = 15 J (the KE in the CM frame, ½μv² with μ = 1.2 kg) can be lost, in a perfectly inelastic collision.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-work-energy-power-125","question":"A 1 kg particle moves along the x-axis with potential energy U(x) = x⁴ − 8x² joule (x in metres). It is nudged from rest at x = 0 with negligible speed. Its speed when it passes the point of minimum potential energy on the positive side is:","options":["4 m/s","4√2 m/s","8 m/s","2√2 m/s"],"answer":1,"explanation":"dU/dx = 4x³ − 16x = 0 gives x = 0 (a maximum, unstable) and x = ±2 m (minima). U(0) = 0 and U(2) = 16 − 32 = −16 J. All 16 J becomes kinetic energy: v = √(2 × 16) = 4√2 ≈ 5.66 m/s.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-work-energy-power-126","question":"A 1 kg block on a rough floor (μ = 0.2) is attached to a wall by a horizontal spring of force constant 100 N/m at its natural length. A constant horizontal force of 10 N then pulls the block away from the wall (g = 10 m/s²). The maximum extension of the spring is:","options":["0.16 m","0.2 m","0.08 m","0.12 m"],"answer":0,"explanation":"At maximum extension the block is momentarily at rest, so the work–energy theorem gives Fx − μmgx = ½kx². Thus x = 2(F − μmg)/k = 2 × 8/100 = 0.16 m, twice the equilibrium extension 0.08 m.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-work-energy-power-127","question":"A 2 kg block is released from rest at the top of a rough incline 5 m high and reaches the bottom with a speed of 6 m/s (g = 10 m/s²). The work done on it by friction is:","options":["+64 J","−36 J","−100 J","−64 J"],"answer":3,"explanation":"Work–energy theorem: W_gravity + W_friction = ΔK. W_gravity = mgh = 100 J and ΔK = ½ × 2 × 36 = 36 J, so W_friction = 36 − 100 = −64 J. The normal force does no work.","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-work-energy-power-128","question":"A pendulum bob of mass m on a 1 m string is released from rest with the string at 60° to the vertical. At the lowest point it strikes a block of the same mass m resting on a smooth floor; the coefficient of restitution is 0.5. After the collision, the bob rises to a height of:","options":["6.25 cm","12.5 cm","zero","3.125 cm"],"answer":3,"explanation":"Speed at impact: v² = 2g × 0.5 = 10. For equal masses, the bob's velocity after impact is (1 − e)v/2 = v/4 and the block's is (1 + e)v/2 = 3v/4. The bob then rises (1/16) × 0.5 m = 0.03125 m = 3.125 cm.","difficulty":"very-hard","source":"JEE Advanced pattern"},
];

export default questions;
